// === INPUT ==============================================================
  const keys = new Set();
  function reset() { console.log('reset called'); }
  document.addEventListener('keydown', (ev) => { if (ev.key === 'r' || ev.key === 'R') { reset(); return; } keys.add(ev.key); });
  document.addEventListener('keyup', (ev) => { keys.delete(ev.key); });
  const restartBtn = document.getElementById('restart');
  if (restartBtn) restartBtn.addEventListener('click', reset);

  // === AUDIO (lazy) =======================================================
  let audioCtx = null;
  function beep(freq, durSec) {
    try {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'square';
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0.05, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + durSec);
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start();
      osc.stop(audioCtx.currentTime + durSec);
    } catch (e) {
      // silent fail
    }
  }

